	"os"
)

var scanner *bufio.Scanner
var tokens []string
var index int

func initScanner() {
	scanner = bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024*1024)
}

func nextLine() string {
	if !scanner.Scan() {
		panic("ArrayIndexOutOfBoundsException: There is no more input")
	}
	return scanner.Text()
}

func nextInt() int {
	for index >= len(tokens) {
		line := nextLine()
		tokens = splitSpace(line)
		index = 0
	}
	val := tokens[index]
	index++
	var n int
	fmt.Sscanf(val, "%d", &n)
	return n
}

func next() string {
	for index >= len(tokens) {
		line := nextLine()
		tokens = splitSpace(line)
		index = 0
	}
	val := tokens[index]
	index++
	return val
}

func splitSpace(s string) []string {
	var result []string
	current := ""
	for _, c := range s {
		if c == ' ' {
			if current != "" {
				result = append(result, current)
				current = ""
			}
		} else {
			current += string(c)
		}
	}
	if current != "" {
		result = append(result, current)
	}
	return result
}

func main() {
	initScanner()
	N := nextInt()
	s := next()
	sf := 0
	fs := 0
	for i := 0; i < N-1; i++ {
		if s[i] == 'F' && s[i+1] == 'S' {
